use derive_setters :: Setters ; use serde :: { Deserialize , Serialize } ; use serde_json :: { Map , Value } ; use crate :: { Agent , Environment , File , Model , Skill } ; # [doc = " Configuration values required by tool description templates."] # [doc = ""] # [doc = " Populated from [`ForgeConfig`] by the application layer and injected into"] # [doc = " [`SystemContext`] so that Handlebars templates can reference values such as"] # [doc = " `{{config.maxReadSize}}` without coupling `SystemContext` to `ForgeConfig`."] # [derive (Debug , Clone , PartialEq , Serialize , Deserialize , Default)] # [serde (rename_all = "camelCase")] pub struct TemplateConfig { # [doc = " Maximum number of lines returned by a single file read (maps to"] # [doc = " `ForgeConfig::max_read_lines`)."] pub max_read_size : usize , # [doc = " Maximum characters per line before truncation (maps to"] # [doc = " `ForgeConfig::max_line_chars`)."] pub max_line_length : usize , # [doc = " Maximum image size in bytes accepted by the read tool (maps to"] # [doc = " `ForgeConfig::max_image_size_bytes`)."] pub max_image_size : usize , # [doc = " Maximum prefix lines kept when truncating shell stdout (maps to"] # [doc = " `ForgeConfig::max_stdout_prefix_lines`)."] pub stdout_max_prefix_length : usize , # [doc = " Maximum suffix lines kept when truncating shell stdout (maps to"] # [doc = " `ForgeConfig::max_stdout_suffix_lines`)."] pub stdout_max_suffix_length : usize , # [doc = " Maximum characters per line in shell stdout before truncation (maps to"] # [doc = " `ForgeConfig::max_stdout_line_chars`)."] pub stdout_max_line_length : usize , }